/* GENERATED by scripts/split_mockup.py from the mockup in analysis/.
   Edit the mockup, not this file, until the mockup is retired. */
"use strict";

/* ----------------------------------------------------------------------------
   DATA

   Two JSON blocks, and they are separate on purpose.

   #journey-data is `site.data.journey` -- i.e. data/journey.json exactly as
   scripts/build_journey.py wrote it. That script is the disclosure boundary
   and deliberately has no idea a blog exists.

   #journey-posts is generated by Liquid from `site.posts` at build time, so
   URLs follow whatever `permalink:` is set to, titles and published state are
   always current, and the private repo never has to carry a copy. Drafts
   (published: false) never appear in site.posts, so they cannot leak.

   Merging them here rather than in a build step is what removes
   scripts/splice_mockup.py: nothing has to rewrite a file to keep `posts` and
   the health data in one object any more.
   -------------------------------------------------------------------------- */
const J = (() => {
  const read = id => {
    const el = document.getElementById(id);
    if (!el) throw new Error("journey: missing #" + id + " -- the page template did not emit it");
    return JSON.parse(el.textContent);
  };
  const data = read("journey-data");
  data.posts = read("journey-posts");
  return data;
})();

/* ============================ scaffolding ============================ */

const DAY = 864e5;
const t = s => Date.parse(s + "T12:00:00Z");
const T0 = t(J.window.start), T1 = t(J.window.end);
const SVGNS = "http://www.w3.org/2000/svg";
const MON = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

const svg = document.getElementById("svg");
const tip = document.getElementById("tip");
const wrap = document.getElementById("wrap");

const W = 900, H = 640;
const M = { l: 60, r: 18 };
const PW = W - M.l - M.r;
const RIB_Y = 8, RIB_H = 16;          // clickable phase ribbon, above the plot
// VGAP was 42 when three panels shared the budget. A fourth panel spends a
// whole gap on top of splitting the same 404px, and 126px of inter-panel air
// is dead space the panels need more than the layout does. The gap still only
// has to clear a panel title set at p.y - 6.
const TOP = 44, BUDGET = 404, VGAP = 34;
const AXIS_Y = TOP + BUDGET;          // 448 — fixed, so toggling a series
const COV_Y  = 506, COV_H = 18;       //        never reflows everything below
const RAIL_Y = 582;
const GUTTER = 36;

const ORDER = ["waist", "weight", "vo2max", "index"];
const P = {
  waist:  { key:"waist",  data:"waist_in",  dom:[42.2,48.6], step:2,  unit:"in", dp:2, color:"var(--c-waist)",  title:"Waist  in" },
  weight: { key:"weight", data:"weight_lb", dom:[228,264],   step:10, unit:"lb", dp:1, color:"var(--c-weight)", title:"Weight  lb" },
  /* Garmin's own estimate, and the only number on this page that is not
     self-relative -- 45 means the same thing here as it does for anyone else.
     That is exactly why it does NOT join the index panel: sharing an axis with
     two 0-100 self-relative indices would imply a comparability neither of
     them has.

     dots:false because 414 points over six years is a smear, not a series of
     marks. snap:false because VO2max moves in single points and an axis
     snapped out to multiples of 5 would flatten every change worth seeing. */
  vo2max: { key:"vo2max", data:"vo2max", dom:[28,46], step:5, unit:"", dp:1,
            // Least hungry panel here: one sparse line, one endpoint label,
            // no marks. A fourth panel costs a whole VGAP out of a fixed
            // budget, so it gives that room back to the index panel rather
            // than taking an equal quarter.
            dots:false, pad:0.08, snap:false, flex:0.85, color:"var(--c-vo2)",
            title:"VO\u2082max  ml/kg/min      Garmin estimate" },
  // Two lines, one panel, one scale. They are the same kind of number -- a
  // self-relative 0-100 index -- so they share an axis honestly. Weight and
  // waist could not: lb and in on one axis is the dual-axis trick, where the
  // crossing point is chosen by whoever drew it.
  index:  { key:"index", dom:[20,80], step:10, unit:"", dp:1, dots:false, pad:0.03, snap:false, flex:1.9,
            title:"Health  ·  Activity      index, 50 = own median week",
            lines: [
              { key:"health",   data:"health_index",   color:"var(--c-health)",   name:"Health" },
              { key:"activity", data:"activity_index", color:"var(--c-activity)", name:"Activity" }
            ] }
};
// Single-line panels are the degenerate case of a multi-line one.
const linesOf = p => p.lines || [{ data:p.data, color:p.color, name:p.title }];

/* Did this week run on fewer inputs than the rest of its own line?

   Compared against what the series actually reaches, not against a fixed
   number. The activity index gains a third input (intensity minutes) as soon
   as a schema-refresh pull backfills it, and a hardcoded threshold would then
   either dash nothing or dash everything. `index_scale.full` is measured from
   the published data for exactly this reason. */
const fullParts = key => (J.index_scale && J.index_scale.full && J.index_scale.full[key]) || 2;
const thin = (key, q) => !!q && q.parts < fullParts(key) - 0.5;

// Minimum baseline separation between two labels that overlap horizontally.
// Comfortably over the 12.5px type they are set in.
const LABEL_GAP = 16;

/* Place an already-created text element in a free vertical slot.

   Purely vertical nudging over-corrects: two labels at opposite ends of the
   panel push each other around despite never touching. This only moves a label
   when the two actually overlap horizontally, and it walks in whichever
   direction the label was already leaning, so a mark above a peak stays above
   it.

   The horizontal extent is MEASURED off the rendered element rather than
   estimated from character count. Estimating undercounts a string like
   "highest · Dec 2025" — proportional digits, an en-space either side of the
   middot — and an undercount reads as "these do not overlap" right up until
   they visibly do. */
function placeLabel(p, el, y, prefer) {
  p._labels = p._labels || [];
  const box = el.getBBox();
  const x0 = box.x, x1 = box.x + box.width;
  const top = p.y + 11, bot = p.y + p.h - 3;
  const free = v => !p._labels.some(L => x1 > L.x0 && x0 < L.x1 && Math.abs(v - L.y) < LABEL_GAP);
  // Walk the preferred way first, then the other way. Clamping AFTER the walk
  // was a bug: a label pushed past the panel edge got snapped back on top of
  // whatever it had just stepped over, which is exactly the collision the walk
  // existed to avoid.
  const dir = prefer === "up" ? -1 : 1;
  let best = null;
  for (const d of [dir, -dir]) {
    for (let k = 0; k <= 8; k++) {
      const v = y + d * k * LABEL_GAP;
      if (v < top || v > bot) break;
      if (free(v)) { best = v; break; }
    }
    if (best !== null) break;
  }
  y = best ?? clamp(y, top, bot);
  p._labels.push({ x0, x1, y });
  el.setAttribute("y", y);
  return y;
}

const S = {
  // Opens on the continuous era. "All" still reaches the 2020 island.
  z0: T0, z1: T1,
  series: { waist: true, weight: true, vo2max: true, index: true },
  showPhase: true, showPost: true, showRace: true,
  sel: null,        // pinned  {kind, ...}
  hoverTs: null,    // transient crosshair
  brush: null       // [x0,x1] while dragging
};

const slug = s => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"")
  .replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
/* ---------------------------------------------------------------------------
   Piecewise time scale.

   A linear decade is dominated by its emptiness: 3.5 blank years sit between
   the recalled peak and the first weigh-in, and another 19 months sit inside
   the 2021-23 fragments. Linearly that is over half the width spent on
   nothing, which squeezes the part that has data into a corner.

   So time inside a gap buys less width than time inside data. Gaps grow
   logarithmically -- a 60-day hole stays roughly true to scale, a 3.5-year
   one compresses about sevenfold -- and the hatch already tells the reader
   exactly where that is happening. Order is preserved and nothing is hidden
   or reordered; only the metric changes, and only where there is nothing to
   measure.
   --------------------------------------------------------------------------- */
const GAP_MIN_DAYS = 60;
// Tuned so ~60d passes through near 1:1 and long gaps flatten hard.
const gapEquiv = days => 34 * Math.log(1 + days / 60);

function occupancy() {
  const set = new Set();
  const add = arr => (arr || []).forEach(o => set.add(t(o.d)));
  // Every series, not just the visible ones — toggling a panel must not slide
  // the time axis under the panels that stayed on.
  add(J.weight_lb); add(J.waist_in); add(J.anchors); add(J.races); add(J.posts);
  add(J.health_index); add(J.activity_index);
  return [...set].sort((a, b) => a - b);
}

let SEG = [];
function buildScale() {
  const pts = occupancy().filter(v => v >= S.z0 && v <= S.z1);
  const bounds = [S.z0, ...pts, S.z1];
  SEG = []; let acc = 0;
  for (let i = 1; i < bounds.length; i++) {
    const a = bounds[i - 1], b = bounds[i];
    if (b <= a) continue;
    const days = (b - a) / DAY;
    const gap = days > GAP_MIN_DAYS;
    const eq = gap ? gapEquiv(days) : days;
    SEG.push({ a, b, days, gap, eq, acc });
    acc += eq;
  }
  SEG.total = acc || 1;
}

const x = d => {
  if (!SEG.length) return M.l;
  if (d <= SEG[0].a) return M.l;
  if (d >= SEG[SEG.length - 1].b) return M.l + PW;
  for (const s of SEG) {
    if (d >= s.a && d <= s.b) {
      return M.l + (s.acc + ((d - s.a) / DAY / s.days) * s.eq) / SEG.total * PW;
    }
  }
  return M.l + PW;
};

const tsAt = px => {
  if (!SEG.length) return S.z0;
  const f = Math.max(0, Math.min(1, (px - M.l) / PW)) * SEG.total;
  for (const s of SEG) {
    if (f >= s.acc && f <= s.acc + s.eq) {
      return s.a + ((f - s.acc) / s.eq) * s.days * DAY;
    }
  }
  return S.z1;
};

/* Compressed stretches are marked explicitly rather than left to be inferred
   from a suspiciously short year. */
function drawScaleGaps(g) {
  SEG.filter(s => s.gap).forEach(s => {
    const xa = x(s.a), xb = x(s.b), w = xb - xa;
    if (w < 1) return;
    el("rect", { x:xa, y:TOP, width:w, height:AXIS_Y - TOP, fill:"rgba(18,18,42,.55)" }, g);
    el("rect", { x:xa, y:TOP, width:w, height:AXIS_Y - TOP, fill:"url(#hatch)" }, g);
    [xa, xb].forEach(xx => el("line", { x1:xx, y1:TOP, x2:xx, y2:AXIS_Y,
      stroke:"rgba(255,255,255,.13)", "stroke-width":1 }, g));
    const yrs = s.days / 365.25;
    const label = yrs >= 1 ? yrs.toFixed(1) + " yr" : Math.round(s.days / 30.4) + " mo";
    if (w > 24) {
      el("text", { x:(xa + xb) / 2, y:TOP + 13, "text-anchor":"middle",
                   fill:"rgba(255,255,255,.55)", "font-size":10 }, g).textContent = label;
    }
  });
}
/* Domains are recomputed per draw from whatever is in view. A fixed range
   either clips the 2020 island (271 lb in the 2021 fragment) or flattens the
   2024-26 detail to fit it; neither is acceptable. */
function fitDomain(p) {
  const vs = linesOf(p).flatMap(ln => J[ln.data].filter(q => inZoom(t(q.d))).map(q => q.v));
  // The recalled peak is what the whole weight plot is read against, so it
  // has to stay on-scale even though it is not part of the series.
  if (p.key === "weight") (J.anchors || []).forEach(a => vs.push(a.v));
  if (!vs.length) return;
  const lo = Math.min(...vs), hi = Math.max(...vs);
  const pad = Math.max((hi - lo) * (p.pad ?? 0.15), p.snap === false ? 0.5 : p.step * 0.6);
  // Snapping the ENDS out to whole gridline multiples is right for a panel
  // whose axis wants round numbers, and wrong for one whose data occupies a
  // narrow band: a 16-74 index spread snapped to a step of 10 becomes a 10-90
  // axis, and the lines then use two thirds of the height they were given.
  // Gridlines are still drawn on the nice multiples inside the domain either
  // way — only the endpoints differ.
  p.dom = p.snap === false
    ? [lo - pad, hi + pad]
    : [Math.floor((lo - pad) / p.step) * p.step, Math.ceil((hi + pad) / p.step) * p.step];
}
const yOf = (p, v) => p.y + p.h - (v - p.dom[0]) / (p.dom[1] - p.dom[0]) * p.h;
const fmt  = d => new Date(d).toLocaleDateString("en-US", { month:"short", day:"numeric", year:"numeric", timeZone:"UTC" });
const fmtM = d => new Date(d).toLocaleDateString("en-US", { month:"short", year:"numeric", timeZone:"UTC" });
const clamp = (v,a,b) => Math.max(a, Math.min(b, v));
const mmss = s => Math.floor(s/60) + ":" + String(s % 60).padStart(2, "0");

const el = (n, a, parent) => {
  const e = document.createElementNS(SVGNS, n);
  for (const k in a) e.setAttribute(k, a[k]);
  (parent || svg).appendChild(e);
  return e;
};

/* persistent defs */
const defs = el("defs", {});
const hatch = el("pattern", { id:"hatch", width:6, height:6, patternUnits:"userSpaceOnUse", patternTransform:"rotate(45)" }, defs);
el("rect", { width:6, height:6, fill:"transparent" }, hatch);
el("line", { x1:0, y1:0, x2:0, y2:6, stroke:"rgba(255,255,255,.13)", "stroke-width":1.5 }, hatch);
const clip = el("clipPath", { id:"clipPlots" }, defs);
el("rect", { x:M.l, y:0, width:PW, height:AXIS_Y }, clip);

/* which plots are visible, and how tall */
function layoutPlots() {
  const vis = ORDER.filter(k => S.series[k]);
  vis.forEach(k => fitDomain(P[k]));
  let y = TOP;
  // Panels are not equally hungry. Waist is 22 points on a 6-inch range; the
  // index panel carries 560 points, two lines and four labels. Splitting the
  // budget evenly starves the one doing the most work.
  const span = BUDGET - VGAP * Math.max(0, vis.length - 1);
  const total = vis.reduce((a, k) => a + (P[k].flex ?? 1), 0) || 1;
  vis.forEach(k => {
    const h = span * (P[k].flex ?? 1) / total;
    P[k].y = y; P[k].h = h; y += h + VGAP;
  });
  return vis;
}

const inZoom = ts => ts >= S.z0 && ts <= S.z1;
const visible = pts => pts.filter(q => inZoom(t(q.d)));

/* ============================ draw ============================ */

let L = {};

/* The hit rect must SURVIVE redraws. A click only fires when pointerdown and
   pointerup land on the same element, and hovering redraws the chart on every
   pointermove — so rebuilding this rect each frame silently breaks every click.
   It is created once, and each draw inserts the new layers underneath it. */
const hitG = el("g", {});
const hit = el("rect", { class:"hit", x:M.l, y:TOP, width:PW, height:AXIS_Y-TOP, fill:"transparent" }, hitG);
hit.setAttribute("pointer-events", "all");

const mkLayer = attrs => {
  const g = document.createElementNS(SVGNS, "g");
  for (const k in attrs) g.setAttribute(k, attrs[k]);
  svg.insertBefore(g, hitG);
  return g;
};

function draw() {
  buildScale();
  [...svg.childNodes].forEach(n => { if (n !== defs && n !== hitG) svg.removeChild(n); });
  const vis = layoutPlots();

  L = {};
  L.phase = mkLayer({});
  L.grid  = mkLayer({});
  L.gap   = mkLayer({ "clip-path":"url(#clipPlots)" });
  L.data  = mkLayer({ "clip-path":"url(#clipPlots)" });
  L.axis  = mkLayer({});
  L.rail  = mkLayer({});
  L.over  = mkLayer({ "pointer-events":"none" });
  L.ribbon = el("g", {});   // appended AFTER the hit rect, so it stays clickable

  drawScaleGaps(L.phase);
  drawPhases();
  vis.forEach(k => { drawGaps(P[k]); drawPlot(P[k]); });
  if (!vis.length) {
    el("text", { x: W/2, y: TOP + BUDGET/2, "text-anchor":"middle", fill:"var(--text-faint)", "font-size":13 }, L.data)
      .textContent = "Both series hidden — turn one back on in the legend";
  }
  drawXAxis();
  drawCoverage();
  drawRail();
  drawOverlay();
  drawPhaseRibbon();
}

/* Bands behind the plot are passive background — the transparent hit rect for
   hover/scrub covers the whole plot area, so nothing under it can be clicked.
   The clickable affordance is the ribbon above the plot instead. */
function drawPhases() {
  if (!S.showPhase) return;
  const g = L.phase, top = TOP, bot = AXIS_Y;

  const preX = x(t(J.phases[0].from));
  if (preX > M.l && preX < M.l + PW) {
    el("line", { x1:preX, y1:top, x2:preX, y2:bot, stroke:"rgba(255,255,255,.16)", "stroke-width":1 }, g);
  }

  /* Bands are NEUTRAL on purpose. Tinting them blue/amber would reuse the two
     series hues for something that is not a series. Direction rides on a glyph
     in the ribbon instead. */
  J.phases.forEach((p, i) => {
    const a = clamp(x(t(p.from)), M.l, M.l + PW);
    const b = clamp(x(t(p.to)),   M.l, M.l + PW);
    if (b - a <= 0) return;
    const on = S.sel && S.sel.kind === "phase" && S.sel.p.id === p.id;
    const band = p.tier === "notebook"
      ? (i % 2 ? "rgba(255,255,255,.03)" : "rgba(255,255,255,.012)")
      : (i % 2 ? "rgba(255,255,255,.055)" : "rgba(255,255,255,.025)");
    el("rect", { x:a, y:top, width:b-a, height:bot-top, "pointer-events":"none",
                 fill: on ? "rgba(100,180,232,.13)" : band }, g);
    el("line", { x1:a, y1:top, x2:a, y2:bot, "pointer-events":"none",
                 stroke: on ? "rgba(100,180,232,.5)" : "rgba(255,255,255,.08)", "stroke-width":1 }, g);
  });
}

function drawPhaseRibbon() {
  if (!S.showPhase) return;
  const g = L.ribbon;
  const glyph = { down:"↓", up:"↑", flat:"→" };

  J.phases.forEach(p => {
    const a = clamp(x(t(p.from)), M.l, M.l + PW);
    const b = clamp(x(t(p.to)),   M.l, M.l + PW);
    const w = b - a;
    if (w <= 1) return;
    const on = S.sel && S.sel.kind === "phase" && S.sel.p.id === p.id;
    const gg = el("g", { class:"phaseband", tabindex:0, role:"button",
                         "aria-label":"Phase " + p.id + ", " + p.name + ", " + p.cov + " percent coverage" }, g);
    // Notebook-tier chips sit lower and read fainter: a different instrument,
    // not a weaker phase. Nothing about them should invite rate comparison.
    const nb = p.tier === "notebook";
    el("rect", { x:a+1, y:RIB_Y + (nb ? 3 : 0), width:w-2, height:RIB_H - (nb ? 6 : 0), rx:2,
                 fill: on ? "rgba(100,180,232,.3)" : (nb ? "rgba(255,255,255,.03)" : "rgba(255,255,255,.08)"),
                 stroke: on ? "rgba(100,180,232,.65)" : "rgba(255,255,255,.12)", "stroke-width":1,
                 "stroke-dasharray": nb ? "3 2" : "none" }, gg);
    if (w > 26) {
      el("text", { x:a + w/2, y:RIB_Y + 11.5, "text-anchor":"middle", class:"phase-label",
                   fill: on ? "#dbeeff" : "rgba(255,255,255,.6)" }, gg)
        .textContent = p.id + " " + glyph[p.dir];
    }
    bind(gg, () => select({ kind:"phase", p }),
             e => tipAt(e, `<div class="t-d">Phase ${p.id} · ${p.name}</div>` +
               `<div class="t-r">${fmt(t(p.from))} – ${fmt(t(p.to))}</div>` +
               `<div class="t-r">Rate<b>${p.rate || "not enough data"}</b></div>` +
               (nb ? `<div class="t-r">Readings<b>${p.n}</b></div>` +
                     `<div class="t-n">Monthly notebook readings, not the daily series — this rate is not comparable to phases A–E.</div>`
                   : `<div class="t-r">Coverage<b>${p.cov}%</b></div>`)));
  });

  el("text", { x:M.l-8, y:RIB_Y+11.5, "text-anchor":"end", class:"phase-label",
               fill:"var(--text-faint)" }, g).textContent = "Phase";
}

function gapsFor(pts) {
  const out = [];
  for (let i = 1; i < pts.length; i++) {
    const a = t(pts[i-1].d), b = t(pts[i].d);
    if ((b - a) / DAY > J.break_days) out.push([a, b]);
  }
  return out;
}

/* Each plot is hatched from ITS OWN gaps — the tape and the home scale were
   not always filled in on the same day. */
function drawGaps(p) {
  const g = L.gap;
  // A gap is only a gap for this panel if EVERY line in it is missing, so the
  // hatch runs over the union of the panel's points rather than one line's.
  // Hatching where one of two lines still has data would call a measured
  // stretch blank.
  const all = linesOf(p).flatMap(ln => J[ln.data]).sort((q, r) => t(q.d) - t(r.d));
  gapsFor(all).forEach(([a, b]) => {
    const xa = x(a), xb = x(b);
    if (xb < M.l || xa > M.l + PW) return;
    el("rect", { x:xa, y:p.y, width:xb-xa, height:p.h, fill:"rgba(18,18,42,.45)" }, g);
    el("rect", { x:xa, y:p.y, width:xb-xa, height:p.h, fill:"url(#hatch)" }, g);
    const months = Math.round((b - a) / DAY / 30.4);
    const ca = Math.max(xa, M.l), cb = Math.min(xb, M.l + PW);
    if (cb - ca > 46) {
      el("text", { x:(ca+cb)/2, y:p.y + p.h/2 + 4, "text-anchor":"middle",
                   fill:"rgba(255,255,255,.45)", "font-size":10.5 }, g).textContent = months + " mo";
    }
  });
}

function drawPlot(p) {
  const g = L.data;
  const [lo, hi] = p.dom;

  for (let v = Math.ceil(lo/p.step)*p.step; v <= hi; v += p.step) {
    const yy = yOf(p, v);
    el("line", { x1:M.l, y1:yy, x2:W-M.r, y2:yy, stroke:"var(--grid)", "stroke-width":1 }, L.grid);
    el("text", { x:M.l-8, y:yy+3.5, "text-anchor":"end", class:"ylab" }, L.grid).textContent = v;
  }
  el("text", { x:M.l, y:p.y-6, class:"axis-title" }, L.grid).textContent = p.title;

  p._labels = [];
  // Two passes over the lines, because label placement is first-come-first
  // served and the panel's marks live on ONE line while the endpoint labels
  // belong to all of them. Deferring the marks to a second pass is what stops
  // the health line's "lowest · Mar 2022" from claiming a slot that boxes in
  // the activity line's endpoint label -- nine pixels of horizontal overlap
  // was enough to block its whole upward escape and push it 36px onto the
  // wrong curve. Ordering within a single line could not fix that; the
  // conflict is across lines.
  const marks = [];
  linesOf(p).forEach(ln => drawLine(p, ln, fn => marks.push(fn)));
  marks.forEach(fn => fn());

  // Recalled anchors are rules across the plot, never marks on the series --
  // there is no reading here to join a line to.
  if (p.key === "weight") (J.anchors || []).forEach(a => {
    const ay = yOf(p, a.v), ax = x(t(a.d));
    // The level, held across the whole plot -- everything measured sits under it.
    el("line", { x1:M.l, y1:ay, x2:W-M.r, y2:ay, stroke:"rgba(217,160,91,.45)",
                 "stroke-width":1.5, "stroke-dasharray":"5 4" }, g);
    // The starting point itself. Drawn hollow and never joined to the series:
    // there is no measurement here, and the years between are genuinely blank.
    const first = J[p.data][0];
    if (first) {
      el("path", { d:`M${ax} ${ay} L${x(t(first.d))} ${yOf(p, first.v)}`, fill:"none",
                   stroke:"rgba(217,160,91,.3)", "stroke-width":1.5,
                   "stroke-dasharray":"2 5" }, g);
    }
    el("circle", { cx:ax, cy:ay, r:6, fill:"var(--bg-primary)",
                   stroke:"#e0b077", "stroke-width":2.5 }, g);
    el("text", { x:ax + 12, y:ay - 9, fill:"#e0b077", "font-size":12.5 }, g)
      .textContent = `~${a.v.toFixed(0)} lb — where it starts`;
    el("text", { x:ax + 12, y:ay + 6, fill:"var(--text-faint)", "font-size":10 }, g)
      .textContent = "end of 2016 · recalled, no scale reading";
  });

}

/* One series inside a panel. Split out of drawPlot so the index panel can run
   it twice against a shared scale. */
function drawLine(p, ln, defer = fn => fn()) {
  const g = L.data, pts = J[ln.data] || [];
  if (!pts.length) return;
  const col = ln.color;

  // segments broken at real gaps — nothing is drawn through a gap
  const segs = [];
  let seg = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    if ((t(pts[i].d) - t(pts[i-1].d)) / DAY > J.break_days) { segs.push(seg); seg = []; }
    seg.push(pts[i]);
  }
  segs.push(seg);

  // A weekly index is mostly noise at this span — one bad night, one long
  // Saturday. The raw weeks stay visible because hiding the scatter would
  // oversell how smooth any of this is, but the readable line is the trend.
  const hasTrend = pts.some(q => q.t != null);
  const path = (s, f) => s.map((q,i) => (i?"L":"M") + x(t(q.d)).toFixed(1) + " " + yOf(p,f(q)).toFixed(1)).join(" ");

  segs.forEach(s => {
    if (s.length < 2) return;
    const d = path(s, q => q.v);
    // The filled area under a line only reads as "how much" when there is one
    // line. Two overlapping washes read as a third colour that means nothing,
    // so the index panel draws strokes alone.
    if (!p.lines) {
      el("path", { d: d + " L" + x(t(s[s.length-1].d)).toFixed(1) + " " + (p.y+p.h) +
                      " L" + x(t(s[0].d)).toFixed(1) + " " + (p.y+p.h) + " Z",
                   fill:col, opacity:.07 }, g);
    }
    el("path", { d, fill:"none", stroke:col, "stroke-width": hasTrend ? 1 : 2,
                 opacity: hasTrend ? .3 : 1,
                 "stroke-linejoin":"round", "stroke-linecap":"round" }, g);
  });

  // The trend, drawn only across runs where the rolling window was actually
  // full enough to have one. A missing `t` breaks the line rather than joining
  // across it.
  if (hasTrend) segs.forEach(s => {
    let run = [];
    const flush = () => {
      if (run.length > 1) {
        el("path", { d: path(run, q => q.t), fill:"none", stroke:col, "stroke-width":2.4,
                     "stroke-linejoin":"round", "stroke-linecap":"round" }, g);
      }
      run = [];
    };
    s.forEach(q => q.t == null ? flush() : run.push(q));
    flush();
  });

  // Where a week scored on one input instead of two, overprint dashed. Before
  // April 2023 there is no HRV at all, so the health line over that stretch is
  // resting heart rate alone — a weaker claim wearing the same colour, and it
  // should not look like the rest of the line.
  segs.forEach(s => {
    for (let i = 1; i < s.length; i++) {
      const a = s[i-1], b = s[i];
      if (!(thin(ln.key, b) && thin(ln.key, a))) continue;
      if (hasTrend && (a.t == null || b.t == null)) continue;
      const f = hasTrend ? (q => q.t) : (q => q.v);
      const d = `M${x(t(a.d)).toFixed(1)} ${yOf(p,f(a)).toFixed(1)} L${x(t(b.d)).toFixed(1)} ${yOf(p,f(b)).toFixed(1)}`;
      el("path", { d, fill:"none", stroke:"var(--bg-primary)", "stroke-width":3 }, g);
      el("path", { d, fill:"none", stroke:col, "stroke-width":2.4, "stroke-dasharray":"3 3" }, g);
    }
  });

  // A weekly index is 250+ points; a dot on each is a smear, not a mark. Only
  // the panels that carry sparse readings get dots.
  if (p.dots !== false) pts.forEach((q, i) => {
    const ts = t(q.d);
    if (ts < S.z0 - DAY || ts > S.z1 + DAY) return;
    const cx = x(ts), cy = yOf(p, q.v);
    if (q.unverified) {
      // Hollow ring, no error bar: the reading did not reconcile, and which
      // way the ambiguous digit falls is not recorded anywhere machine-readable.
      el("circle", { cx, cy, r:4.6, fill:"var(--bg-primary)", stroke:col, "stroke-width":2 }, g);
    } else {
      const last = i === pts.length - 1;
      el("circle", { cx, cy, r:last?4.6:3.2, fill:col, stroke:"var(--bg-primary)", "stroke-width":last?2:1.2 }, g);
    }
  });

  // direct-label the endpoint only, never every point -- and flip it to the
  // left rather than letting it run off the right edge
  const vis = visible(pts);
  if (vis.length) {
    const lp = vis[vis.length-1], lx = x(t(lp.d));
    const val = hasTrend && lp.t != null ? lp.t : lp.v;
    // Multi-line panels name the series too; colour alone is doing less work
    // here than in a panel that holds one thing.
    const label = p.lines ? `${ln.name} ${val.toFixed(0)}` : val.toFixed(1);
    const flip = lx + (label.length * 7.6 + 12) > W - 4;
    // When two lines finish on the same value their labels start on the same
    // pixel, and nudging them both one way drags the loser off its own series.
    // Send the upper line's label up and the lower line's down instead, so
    // each stays on the side its curve is already on.
    const others = linesOf(p).filter(o => o !== ln).map(o => {
      const ov = visible(J[o.data] || []).slice(-1)[0];
      return ov ? (ov.t ?? ov.v) : -Infinity;
    });
    const prefer = others.every(o => val >= o) ? "up" : "down";
    // The label lands on top of the series it names, so it carries a halo of
    // the background colour rather than fighting the line underneath it.
    const et = el("text", { x: flip ? lx - 9 : lx + 9, y: yOf(p, val) + 4,
                 "text-anchor": flip ? "end" : "start",
                 fill: p.lines ? col : "var(--text-bright)", "font-size":12.5,
                 stroke:"var(--bg-primary)", "stroke-width":3.5, "stroke-linejoin":"round",
                 "paint-order":"stroke fill" }, g);
    et.textContent = label;
    placeLabel(p, et, yOf(p, val) + 4, prefer);
  }

  // Marked extremes are placed AFTER the endpoint labels, and the order is
  // load-bearing. An endpoint label IS its line's identity -- pushed off its
  // own curve it names the wrong series -- while a mark keeps a circle on the
  // point it refers to, so it can afford to move. Placed first, a mark that
  // overlapped an endpoint label by nine pixels blocked its whole upward
  // escape and shoved it two steps the other way, 36px from the line it named
  // and closer to the other one.
  // The high and low of the TREND, so they point at the best and worst
  // sustained stretches rather than at a single good or bad week.
  defer(() => pts.filter(q => q.mark && q.t != null).forEach(q => {
    const ts = t(q.d);
    if (ts < S.z0 || ts > S.z1) return;
    const cx = x(ts), cy = yOf(p, q.t), up = q.mark === "high";
    el("circle", { cx, cy, r:5.5, fill:"var(--bg-primary)", stroke:col, "stroke-width":2.5 }, g);
    // Label above a high and below a low, so it never sits on the line it
    // marks — and pulled inboard at the edges rather than clipped.
    const near = cx > M.l + PW - 90, anchor = near ? "end" : cx < M.l + 90 ? "start" : "middle";
    const lx = cx + (anchor === "end" ? 7 : anchor === "start" ? -7 : 0);
    // Sit well clear of the line rather than just off it: the endpoint labels
    // live in the same band at the right edge, and a mark that only just
    // clears the curve starts a nudge cascade that drags them off their own
    // series.
    const mt = el("text", { x:lx, y:cy + (up ? -26 : 24), "text-anchor":anchor, fill:col,
                 "font-size":11.5, stroke:"var(--bg-primary)", "stroke-width":3.5,
                 "stroke-linejoin":"round", "paint-order":"stroke fill" }, g);
    mt.textContent = `${up ? "highest" : "lowest"} · ${fmtM(ts)}`;
    placeLabel(p, mt, cy + (up ? -26 : 24), up ? "up" : "down");
  }));
}

function axisTicks() {
  const months = (S.z1 - S.z0) / DAY / 30.44;
  const step = months > 84 ? 12 : months > 30 ? 3 : months > 14 ? 2 : 1;
  const d0 = new Date(S.z0);
  let y = d0.getUTCFullYear(), m = Math.floor(d0.getUTCMonth() / step) * step;
  const out = [];
  for (let guard = 0; guard < 200; guard++) {
    const ts = Date.UTC(y, m, 1);
    if (ts > S.z1) break;
    if (ts >= S.z0) out.push({ ts, major: m === 0 });
    m += step; if (m > 11) { m -= 12; y++; }
  }
  return out;
}

function drawXAxis() {
  const g = L.axis;
  el("line", { x1:M.l, y1:AXIS_Y, x2:W-M.r, y2:AXIS_Y, stroke:"var(--axis)", "stroke-width":1 }, g);
  const ticks = axisTicks();
  const dense = ticks.length > 16;
  let lastX = -1e9;
  ticks.forEach((k, i) => {
    const xx = x(k.ts);
    // Ticks inside a compressed stretch land on top of each other. Keep the
    // first, drop the rest -- a smeared "2017 2018 2019" reads as noise.
    if (xx - lastX < 34) return;
    lastX = xx;
    el("line", { x1:xx, y1:AXIS_Y, x2:xx, y2:AXIS_Y + (k.major?7:4),
                 stroke: k.major ? "var(--axis)" : "rgba(255,255,255,.09)", "stroke-width":1 }, g);
    if (dense && !k.major && i % 2) return;
    el("text", { x:xx, y:AXIS_Y+19, "text-anchor":"middle",
                 fill: k.major ? "var(--text-secondary)" : "var(--text-faint)",
                 "font-size": k.major ? 11.5 : 10 }, g)
      .textContent = k.major ? new Date(k.ts).getUTCFullYear() : MON[new Date(k.ts).getUTCMonth()];
  });
}

/* Coverage of the DAILY weigh-in series — deliberately labelled apart from the
   hatch above, which means "no tape or scale entry to plot". */
function drawCoverage() {
  const g = L.axis;
  el("text", { x:M.l, y:COV_Y-8, class:"axis-title" }, g)
    .textContent = "Daily weigh-in coverage  — what the phase rates rest on";

  const preX = clamp(x(t(J.phases[0].from)), M.l, M.l + PW);
  if (preX > M.l + 2) {
    el("rect", { x:M.l, y:COV_Y, width:preX-M.l, height:COV_H, fill:"rgba(255,255,255,.035)" }, g);
    if (preX - M.l > 130) {
      el("text", { x:M.l + (preX-M.l)/2, y:COV_Y+12.5, "text-anchor":"middle",
                   fill:"rgba(255,255,255,.4)", "font-size":10 }, g)
        .textContent = "nothing recorded";
    }
  }

  J.phases.forEach(p => {
    // Notebook phases have no daily weigh-ins by definition — drawing a bar
    // for them would invent coverage that does not exist.
    if (p.tier === "notebook") return;
    const a = clamp(x(t(p.from)), M.l, M.l+PW), b = clamp(x(t(p.to)), M.l, M.l+PW);
    const w = b - a;
    if (w <= 1) return;
    el("rect", { x:a+1, y:COV_Y, width:w-2, height:COV_H, fill:"rgba(255,255,255,.05)" }, g);
    const fh = Math.max(1.5, COV_H * p.cov / 100);
    el("rect", { x:a+1, y:COV_Y+COV_H-fh, width:w-2, height:fh,
                 fill: p.rate ? "rgba(255,255,255,.28)" : "rgba(217,160,91,.8)" }, g);
    if (w > 30) {
      el("text", { x:a+w/2, y:COV_Y+COV_H+13, "text-anchor":"middle",
                   fill: p.rate ? "var(--text-secondary)" : "#f0d3ae", "font-size":10 }, g)
        .textContent = p.cov + "%";
    }
  });
}

function drawRail() {
  const g = L.rail;
  el("text", { x:M.l+2, y:RAIL_Y-14, class:"axis-title" }, g).textContent = "Writing & races";
  el("line", { x1:M.l-GUTTER, y1:RAIL_Y, x2:W-M.r, y2:RAIL_Y, stroke:"rgba(255,255,255,.09)", "stroke-width":1 }, g);
  // No gutter any more: the axis now starts at the recalled peak, so every
  // post and race has a real date inside the window.

  let preN = 0;   // shared gutter slot counter: pre-record races, then posts
  let raceN = 0;  // stagger index so clustered races do not overlap
  let lastPostLabelX = -1e9;

  if (S.showRace) J.races.forEach(r => {
    const ts = t(r.d);
    // Races predating the measurement record share the gutter with old posts.
    if (r.pre) {
      const gx = M.l - GUTTER + 11 + preN * 14, gy = RAIL_Y + (preN++ % 2 ? 11 : -11);
      const on0 = S.sel && S.sel.kind === "race" && S.sel.r.d === r.d;
      const g0 = el("g", { class:"pin", tabindex:0, role:"button",
                           "aria-label":r.name + ", " + fmt(ts) + ", before the record" }, g);
      el("path", { d:`M${gx-0.5} ${gy+6} L${gx-0.5} ${gy-8} L${gx+7} ${gy-5} L${gx-0.5} ${gy-2} Z`,
                   class:"pinhead", fill: on0 ? "#fff" : "var(--bg-primary)",
                   stroke:"#cfd6e6", "stroke-width":1.6, "stroke-linejoin":"round" }, g0);
      el("rect", { x:gx-11, y:gy-12, width:24, height:24, fill:"transparent" }, g0);
      bind(g0, () => select({ kind:"race", r }),
               e => tipAt(e, `<div class="t-d">${fmt(ts)} · before the record</div>` +
                 `<div class="t-r"><b style="margin:0;padding:0">${r.name}</b></div>` +
                 `<div class="t-r">Strava elapsed<b>${mmss(r.strava_s)}</b></div>`));
      return;
    }
    if (!inZoom(ts)) return;
    const xx = x(ts);
    const on = S.sel && S.sel.kind === "race" && S.sel.r.d === r.d;
    const lift = (raceN++ % 3) * 9;
    el("line", { x1:xx, y1:TOP, x2:xx, y2:RAIL_Y - lift,
                 stroke: on ? "rgba(255,255,255,.45)" : "rgba(255,255,255,.14)", "stroke-width":1 }, L.phase);
    const gg = el("g", { class:"pin", tabindex:0, role:"button",
                         "aria-label":r.name + ", " + fmt(ts) + ", " + mmss(r.strava_s) }, g);
    // A pennant, so a race never reads as a post or a plotted measurement.
    // Milestones fly a hollow pennant: same kind of marker, not a race result.
    el("path", { d:`M${xx-0.5} ${RAIL_Y+7-lift} L${xx-0.5} ${RAIL_Y-9-lift} L${xx+8} ${RAIL_Y-5.5-lift} L${xx-0.5} ${RAIL_Y-2-lift} Z`,
                 class:"pinhead",
                 fill: on ? "#fff" : (r.milestone ? "var(--bg-primary)" : "#cfd6e6"),
                 stroke: on ? "#fff" : "#cfd6e6", "stroke-width": r.milestone ? 1.6 : 1.2,
                 "stroke-linejoin":"round" }, gg);
    el("rect", { x:xx-11, y:RAIL_Y-15-lift, width:26, height:28, fill:"transparent" }, gg);
    bind(gg, () => select({ kind:"race", r }),
             e => tipAt(e, `<div class="t-d">${fmt(ts)}</div>` +
               `<div class="t-r"><b style="margin:0;padding:0">${r.name}</b></div>` +
               `<div class="t-r">Strava elapsed<b>${mmss(r.strava_s)}</b></div>` +
               (r.place ? `<div class="t-r">Placed<b>${r.place}</b></div>` : "") +
               `<div class="t-n">Over ${(r.gps_m/1000).toFixed(2)} km of GPS distance — not an official chip time.</div>`));
  });

  if (!S.showPost) return;

  J.posts.forEach(po => {
    const ts = t(po.d);
    const pre = !!po.pre;
    if (!pre && !inZoom(ts)) return;
    // Posts predating the record stack in the gutter rather than being drawn
    // at a date the data cannot speak to.
    const xx = pre ? M.l - GUTTER + 11 + preN * 14 : x(ts);
    const stack = pre ? (preN++ % 2 ? 11 : -11) : 0;
    const on = S.sel && S.sel.kind === "post" && S.sel.po.d === po.d;
    const gg = el("g", { class:"pin", tabindex:0, role:"button",
                         "aria-label":po.title + ", " + fmt(ts) + (pre ? ", before the record" : "") }, g);
    if (!pre) {
      el("line", { x1:xx, y1:TOP, x2:xx, y2:RAIL_Y-6,
                   stroke: on ? "rgba(157,111,214,.75)" : "rgba(157,111,214,.3)",
                   "stroke-width": on ? 1.5 : 1 }, L.phase);
    }
    el("circle", { cx:xx, cy:RAIL_Y+stack, r: on ? 6.5 : 5, class:"pinhead",
                   fill: pre && !on ? "var(--bg-primary)" : "var(--c-post)",
                   stroke: on ? "#fff" : "var(--c-post)", "stroke-width":2 }, gg);
    el("rect", { x:xx-13, y:RAIL_Y+stack-13, width:26, height:26, fill:"transparent" }, gg);
    // Compression can push two posts within a few pixels of each other. Label
    // what fits; the pin stays clickable either way and the readout names it.
    if (!pre && (on || xx - lastPostLabelX > 78)) {
      el("text", { x:xx+11, y:RAIL_Y+4, fill: on ? "var(--text-bright)" : "var(--text-secondary)", "font-size":11 }, gg)
        .textContent = po.title;
      lastPostLabelX = xx;
    }
    bind(gg, () => select({ kind:"post", po }),
             e => tipAt(e, `<div class="t-d">${fmt(ts)}${pre ? " · before the record" : ""}</div>` +
                           `<div class="t-r"><b style="margin:0;padding:0">${po.title}</b></div>` +
                           `<div class="t-n">Click to see where I was — then read it.</div>`));
  });
}

/* crosshair + brush live above everything */
function drawOverlay() {
  const g = L.over;
  const ts = S.hoverTs != null ? S.hoverTs : (S.sel && S.sel.ts != null ? S.sel.ts : null);
  const pinned = S.hoverTs == null && S.sel && S.sel.ts != null;

  if (S.brush) {
    const [a, b] = S.brush;
    el("rect", { x:Math.min(a,b), y:TOP, width:Math.abs(b-a), height:AXIS_Y-TOP,
                 fill:"rgba(100,180,232,.14)", stroke:"rgba(100,180,232,.5)", "stroke-width":1 }, g);
    return;
  }
  if (ts == null) return;

  const rec = snapRec(ts);
  if (!rec) return;
  const xx = x(rec.ts);
  el("line", { x1:xx, y1:TOP, x2:xx, y2:AXIS_Y,
               stroke: pinned ? "rgba(255,255,255,.5)" : "rgba(255,255,255,.3)",
               "stroke-width": pinned ? 1.5 : 1 }, g);
  ORDER.filter(k => S.series[k]).forEach(k => {
    const p = P[k];
    linesOf(p).forEach(ln => {
      // Weekly series are stamped on the ISO Monday, so an exact date match
      // finds nothing on five days out of seven. Fall back to the nearest
      // reading this series can still claim describes the hovered date.
      const q = J[ln.data].find(z => z.d === rec.d)
             || nearestWithin(J[ln.data], rec.ts, snapDays(ln.data));
      if (!q) return;
      el("circle", { cx:xx, cy:yOf(p,q.v), r: pinned ? 6 : 5, fill:ln.color,
                     stroke:"var(--bg-primary)", "stroke-width":2 }, g);
    });
  });
}

/* How near a reading must be to the hovered date to describe it.

   Set from each series' own cadence, not one global number. The tape is
   measured about monthly and the indices are weekly, so a single tolerance
   either strands the tape or lets a three-week-old index value pose as
   today's. */
const SNAP_DAYS = { waist_in:21, weight_lb:5, vo2max:14, health_index:4, activity_index:4 };
const snapDays = data => SNAP_DAYS[data] ?? 7;

/* Every date the crosshair may land on: one from EVERY enabled series.

   This used to be `nearest(J.waist_in, ts)` -- the waist tape alone, 22
   readings across six years. Most of the plot was therefore unhoverable: the
   pointer could sit directly on a weight point or a VO2max point and the
   crosshair would jump weeks away to the nearest tape measurement, taking the
   readout with it. Waist is also the sparsest series here and the least
   important, so it was the worst possible thing to key the whole interaction
   on.

   Rebuilt per draw rather than cached across draws, because it depends on the
   zoom window and on which series are switched on -- both of which change
   under the pointer. */
let _poolKey = null, _pool = [];
function hoverPool() {
  const key = S.z0 + ":" + S.z1 + ":" + ORDER.filter(k => S.series[k]).join(",");
  if (key === _poolKey) return _pool;
  const ds = new Set();
  ORDER.filter(k => S.series[k]).forEach(k =>
    linesOf(P[k]).forEach(ln => visible(J[ln.data] || []).forEach(q => ds.add(q.d))));
  _poolKey = key; _pool = [...ds].sort();
  return _pool;
}

// The observation nearest the hovered instant, from any enabled series.
function snapRec(ts) {
  const pool = hoverPool();
  if (!pool.length) return null;
  let best = pool[0], bd = Infinity;
  for (const d of pool) {
    const dd = Math.abs(t(d) - ts);
    if (dd < bd) { best = d; bd = dd; }
  }
  return { d: best, ts: t(best) };
}

function nearest(pts, ts) {
  const vis = visible(pts);
  const pool = vis.length ? vis : pts;
  return pool.reduce((a,b) => Math.abs(t(b.d)-ts) < Math.abs(t(a.d)-ts) ? b : a, pool[0]);
}

/* ============================ interaction ============================ */

function bind(node, onPick, onHover) {
  node.addEventListener("click", e => { e.stopPropagation(); onPick(); });
  node.addEventListener("keydown", e => {
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.stopPropagation(); onPick(); }
  });
  if (onHover) {
    node.addEventListener("pointerenter", e => { if (e.pointerType === "mouse") onHover(e); });
    node.addEventListener("focus", () => { /* focus shows selection ring; tooltip needs a pointer */ });
    node.addEventListener("pointerleave", hideTip);
    node.addEventListener("blur", hideTip);
  }
}

/* One persistent transparent rect drives hover, tap and brush for the whole
   plot area. Pointer Events cover mouse, touch and pen with one code path. */
let suppressClick = false;
(function wireHit() {
  let down = null;

  const localX = e => {
    const r = svg.getBoundingClientRect();
    return (e.clientX - r.left) / r.width * W;
  };

  /* Selection runs off `click`, not `pointerup`. A touch tap synthesizes a
     click even when the browser claims the pointer stream for scrolling, so
     this is the one path that works for mouse, touch and pen alike. */
  hit.addEventListener("click", e => {
    if (suppressClick) { suppressClick = false; return; }
    const rec = snapRec(tsAt(localX(e)));
    if (rec) select({ kind:"reading", d: rec.d, ts: rec.ts });
  });

  // Brush-to-zoom and hover are mouse-only: on touch those gestures belong to
  // the page and to the horizontal scroll container.
  hit.addEventListener("pointermove", e => {
    if (e.pointerType !== "mouse") return;
    const px = localX(e);
    if (down) {
      if (down.moved || Math.abs(px - down.px) > 10) {
        down.moved = true;
        S.brush = [down.px, clamp(px, M.l, M.l + PW)];
        hideTip(); draw();
      }
      return;
    }
    S.hoverTs = tsAt(px);
    draw();
    showReadingTip(e, S.hoverTs);
  });

  hit.addEventListener("pointerdown", e => {
    if (e.pointerType !== "mouse") return;
    down = { px: localX(e), moved: false };
    hit.setPointerCapture(e.pointerId);
  });

  hit.addEventListener("pointerup", e => {
    if (!down) return;
    const px = localX(e);
    if (down.moved && Math.abs(px - down.px) > 10) {
      suppressClick = true;        // a drag is a zoom, not a selection
      setRange(tsAt(Math.min(down.px, px)), tsAt(Math.max(down.px, px)), null);
    }
    S.brush = null; down = null; draw();
  });

  hit.addEventListener("pointercancel", () => { S.brush = null; down = null; draw(); });

  hit.addEventListener("pointerleave", () => {
    if (down) return;
    S.hoverTs = null; hideTip(); draw();
  });
})();

function showReadingTip(e, ts) {
  // A gap in the RECORD, not a gap in the tape. Waist is measured monthly, so
  // its own gaps say nothing about whether anything was recorded that week.
  const rec0 = snapRec(ts);
  const gap = !rec0 || Math.abs(rec0.ts - ts) > 45*DAY;
  if (gap) {
    tipAt(e, `<div class="t-d">${fmtM(ts)}</div><div class="t-n" style="margin-top:0">` +
             `No measurements in this window. The line is broken rather than interpolated — ` +
             `nothing is drawn through a gap.</div>`);
    return;
  }
  const rec = rec0;
  const wa = nearestWithin(J.waist_in, rec.ts, snapDays("waist_in"));
  const we = nearestWithin(J.weight_lb, rec.ts, snapDays("weight_lb"));
  let html = `<div class="t-d">${fmt(rec.ts)}</div>`;
  if (S.series.waist)
    html += wa ? `<div class="t-r"><i style="background:var(--c-waist)"></i>Waist<b>${wa.v.toFixed(2)} in</b></div>`
               : `<div class="t-r"><i style="background:rgba(255,255,255,.2)"></i>Waist<b>—</b></div>`;
  if (S.series.weight)
    html += we ? `<div class="t-r"><i style="background:var(--c-weight)"></i>Weight<b>${we.v.toFixed(1)} lb</b></div>`
               : `<div class="t-r"><i style="background:rgba(255,255,255,.2)"></i>Weight<b>—</b></div>`;
  if (S.series.vo2max) {
    // Nearest within a fortnight: Garmin recalculates only after a qualifying
    // activity, so an exact date match finds nothing on most days. Beyond that
    // the reading is too old to describe the day being hovered.
    const vo = nearestWithin(J.vo2max || [], rec.ts, snapDays("vo2max"));
    html += vo ? `<div class="t-r"><i style="background:var(--c-vo2)"></i>VO\u2082max<b>${vo.v.toFixed(1)}</b></div>`
               : `<div class="t-r"><i style="background:rgba(255,255,255,.2)"></i>VO\u2082max<b>—</b></div>`;
  }
  if (S.series.index) {
    const hi = nearestWithin(J.health_index, rec.ts, snapDays("health_index"));
    const ai = nearestWithin(J.activity_index, rec.ts, snapDays("activity_index"));
    const row = (c, key, name, q) => q
      ? `<div class="t-r"><i style="background:${c}"></i>${name}<b>${q.v.toFixed(0)}${thin(key, q) ? " *" : ""}</b></div>`
      : `<div class="t-r"><i style="background:rgba(255,255,255,.2)"></i>${name}<b>—</b></div>`;
    html += row("var(--c-health)", "health", "Health", hi)
          + row("var(--c-activity)", "activity", "Activity", ai);
    if (thin("health", hi) || thin("activity", ai))
      html += `<div class="t-n">* Scored on fewer inputs than the rest of the line — a weaker number, not an equivalent one.</div>`;
  }
  if (wa && wa.unverified) html += `<div class="t-n">This tape reading never reconciled against the page total — treat it as approximate.</div>`;
  if (!we && S.series.weight) html += `<div class="t-n">No home-scale reading this month. The two scales differ by ~2.9 lb and are never averaged.</div>`;
  tipAt(e, html);
}

function tipAt(e, html) {
  tip.innerHTML = html;
  tip.classList.add("on");
  const r = wrap.getBoundingClientRect();
  let lx = e.clientX - r.left + 16, ly = e.clientY - r.top + 12;
  if (lx + tip.offsetWidth > r.width - 4) lx = e.clientX - r.left - tip.offsetWidth - 16;
  if (ly + tip.offsetHeight > r.height - 4) ly = r.height - tip.offsetHeight - 4;
  tip.style.left = Math.max(4, lx) + "px";
  tip.style.top  = Math.max(4, ly) + "px";
}
const hideTip = () => tip.classList.remove("on");

/* ---------- zoom ---------- */
const RANGES = {
  all:    () => [T0, T1],
  measured: () => [t(J.continuous_from || "2024-01-01"), T1],
  "2020": () => [Date.UTC(2020,4,1), Date.UTC(2020,8,1)],
  "2024": () => [Date.UTC(2024,0,1), Date.UTC(2024,11,31)],
  "2025": () => [Date.UTC(2025,0,1), Date.UTC(2025,11,31)],
  "2026": () => [Date.UTC(2026,0,1), T1],
  regain: () => [Date.UTC(2025,9,1), T1]
};

function setRange(a, b, name) {
  if (b - a < 21 * DAY) return;                 // refuse a useless zoom
  S.z0 = clamp(a, T0, T1); S.z1 = clamp(b, T0, T1);
  document.querySelectorAll("[data-range]").forEach(el2 =>
    el2.setAttribute("aria-pressed", String(el2.dataset.range === name)));
  draw();
}

document.querySelectorAll("[data-range]").forEach(b => {
  b.addEventListener("click", () => {
    const [a, z] = RANGES[b.dataset.range]();
    setRange(a, z, b.dataset.range);
  });
});

/* ---------- selection & readout ---------- */
/* N3 deliberately overlaps Phase A — the notebook window brackets the daily
   one. Where both cover a date the daily series wins: it is the better
   instrument, and returning the notebook phase would attach a "no rate"
   caveat to a window that has a real one. */
const phaseAt = ts => {
  const hit = p => ts >= t(p.from) && ts <= t(p.to);
  return J.phases.find(p => !p.tier && hit(p)) || J.phases.find(hit);
};
function nearestWithin(pts, ts, days) {
  let best = null;
  pts.forEach(q => {
    const dd = Math.abs(t(q.d) - ts);
    if (dd <= days*DAY && (!best || dd < Math.abs(t(best.d) - ts))) best = q;
  });
  return best;
}

function select(sel, opts) {
  if (sel && sel.kind === "post") sel.ts = sel.po.pre ? null : t(sel.po.d);
  if (sel && sel.kind === "race") sel.ts = sel.r.pre ? null : t(sel.r.d);
  S.sel = sel;
  S.hoverTs = null;
  renderReadout();
  draw();
  syncLists();
  document.getElementById("clear").disabled = !sel;
  if (sel && sel.kind === "post" && !sel.po.pre) history.replaceState(null, "", "#" + slug(sel.po.title));
  if (!(opts && opts.quiet)) {
    document.getElementById("readout").scrollIntoView({ block:"nearest", behavior:"smooth" });
  }
}

function renderReadout() {
  const ro = document.getElementById("readout");
  const eyebrow = document.getElementById("ro-eyebrow");
  const title = document.getElementById("ro-title");
  const when  = document.getElementById("ro-when");
  const grid  = document.getElementById("ro-grid");
  const body  = document.getElementById("ro-body");
  const go    = document.getElementById("ro-go");
  const sel = S.sel;

  go.hidden = true;
  grid.innerHTML = "";
  body.classList.remove("empty");

  if (!sel) {
    ro.style.setProperty("--ro-accent", "var(--c-post)");
    eyebrow.textContent = "Where I was when I wrote it";
    title.textContent = "Nothing selected";
    when.textContent = "Pick a post, a phase, or any point on the chart";
    body.classList.add("empty");
    body.textContent = "Click a violet pin on the timeline, a phase band behind it, or any post in " +
      "the list below — this panel will show what the tape and the scale said at that moment, and link straight to the post.";
    return;
  }

  const cell = (k, v, sub) =>
    `<div>${k}<strong>${v}</strong>${sub ? `<span>${sub}</span>` : ""}</div>`;

  if (sel.kind === "phase") {
    const p = sel.p;
    ro.style.setProperty("--ro-accent", "rgba(255,255,255,.35)");
    eyebrow.textContent = "Phase";
    title.textContent = p.id + " · " + p.name;
    when.textContent = fmt(t(p.from)) + " – " + fmt(t(p.to));
    const nb = p.tier === "notebook";
    eyebrow.textContent = nb ? "Phase · notebook tier" : "Phase";
    grid.innerHTML =
      cell("Rate", p.rate || "no rate", p.rate ? "" : (nb ? "only " + p.n + " readings" : "coverage too thin")) +
      cell("Net weight", p.net, "") +
      (p.waist ? cell("Net waist", p.waist, "") : "") +
      (nb ? cell("Readings", String(p.n), "monthly, not fasted-AM")
          : cell("Coverage", p.cov + "%", p.rate ? "" : "direction only"));
    body.textContent = p.say;
    return;
  }

  if (sel.kind === "race") {
    const r = sel.r, ts = t(r.d), ph = phaseAt(ts);
    ro.style.setProperty("--ro-accent", "#cfd6e6");
    eyebrow.textContent = r.milestone ? "Milestone run" : r.social ? "Social run" : "Race";
    title.textContent = r.name;
    when.textContent = fmt(ts) + (ph ? "  ·  Phase " + ph.id + " — " + ph.name : "");
    const wa = r.pre ? null : nearestWithin(J.waist_in, ts, 45);
    const we = r.pre ? null : nearestWithin(J.weight_lb, ts, 45);
    grid.innerHTML =
      cell(r.official_s ? "Official" : "Strava elapsed",
           mmss(r.official_s || r.strava_s),
           r.official_s ? "chip time"
             : (r.gps_m/1000).toFixed(2) + " km GPS · " +
               (r.milestone ? "solo run, not a race" : r.social ? "social run, untimed" : "not official")) +
      (r.place ? cell("Placed", r.place, "") : "") +
      cell("Waist", wa ? wa.v.toFixed(2) + " in" : "—",
           r.pre ? "no record yet" : (wa ? fmtM(t(wa.d)) : "nothing within 45 days")) +
      cell("Weight", we ? we.v.toFixed(1) + " lb" : "—",
           r.pre ? "no record yet" : (we ? fmtM(t(we.d)) : "nothing within 45 days")) +
      (ph ? cell("Trend then", ph.rate || "no rate", ph.cov + "% coverage") : "");
    body.textContent = r.say;
    return;
  }

  if (sel.kind === "reading") {
    const ts = t(sel.d), ph = phaseAt(ts);
    const wa = J.waist_in.find(q => q.d === sel.d);
    const we = J.weight_lb.find(q => q.d === sel.d);
    const po = nearestWithin(J.posts.filter(p => !p.pre), ts, 45);
    ro.style.setProperty("--ro-accent", "var(--c-waist)");
    eyebrow.textContent = "Reading";
    title.textContent = fmt(ts);
    when.textContent = ph ? "Phase " + ph.id + " — " + ph.name : "Before the daily series began";
    grid.innerHTML =
      cell("Waist", wa ? wa.v.toFixed(2) + " in" : "—", wa && wa.unverified ? "unverified reading" : "") +
      cell("Weight", we ? we.v.toFixed(1) + " lb" : "—", we ? "" : "no home-scale entry") +
      (ph ? cell("Trend then", ph.rate || "no rate", ph.cov + "% coverage") : "");
    if (po) {
      body.textContent = "Closest thing I wrote: “" + po.title + "”, " + fmt(t(po.d)) + ".";
      go.href = po.url; go.textContent = "Read “" + po.title + "” →"; go.hidden = false;
    } else {
      body.classList.add("empty");
      body.textContent = "No fitness writing within six weeks of this reading.";
    }
    return;
  }

  // post
  const po = sel.po, ts = t(po.d), ph = phaseAt(ts);
  ro.style.setProperty("--ro-accent", "var(--c-post)");
  eyebrow.textContent = "Where I was when I wrote it";
  title.textContent = po.title;
  when.textContent = fmt(ts) + (ph ? "  ·  Phase " + ph.id + " — " + ph.name : "");
  if (po.pre) {
    grid.innerHTML = cell("Waist", "—", "no record yet") + cell("Weight", "—", "no record yet");
  } else {
    const wa = nearestWithin(J.waist_in, ts, 45), we = nearestWithin(J.weight_lb, ts, 45);
    grid.innerHTML =
      cell("Waist", wa ? wa.v.toFixed(2) + " in" : "—", wa ? fmtM(t(wa.d)) : "nothing within 45 days") +
      cell("Weight", we ? we.v.toFixed(1) + " lb" : "—", we ? fmtM(t(we.d)) : "nothing within 45 days") +
      (ph ? cell("Trend then", ph.rate || "no rate", ph.cov + "% coverage") : "");
  }
  body.textContent = po.say;
  go.href = po.url; go.textContent = "Read the post →"; go.hidden = false;
}

/* ---------- stepping ---------- */
function step(dir) {
  const pts = J.waist_in;
  let i;
  if (S.sel && S.sel.kind === "reading") i = pts.findIndex(q => q.d === S.sel.d) + dir;
  else i = dir > 0 ? 0 : pts.length - 1;
  i = clamp(i, 0, pts.length - 1);
  const rec = pts[i];
  if (!inZoom(t(rec.d))) setRange(T0, T1, "all");
  select({ kind:"reading", d: rec.d, ts: t(rec.d) }, { quiet:true });
}
document.getElementById("prev").addEventListener("click", () => step(-1));
document.getElementById("next").addEventListener("click", () => step(1));
document.getElementById("clear").addEventListener("click", () => {
  select(null, { quiet:true });
  history.replaceState(null, "", location.pathname + location.search);
});

svg.addEventListener("keydown", e => {
  if (e.key === "ArrowRight") { e.preventDefault(); step(1); }
  else if (e.key === "ArrowLeft") { e.preventDefault(); step(-1); }
  else if (e.key === "Escape") { e.preventDefault(); select(null, { quiet:true }); }
  else if (e.key === "Home") { e.preventDefault(); setRange(T0, T1, "all"); }
});

/* ---------- toggles ---------- */
function toggleBtn(id, fn) {
  const b = document.getElementById(id);
  b.addEventListener("click", () => {
    const on = b.getAttribute("aria-pressed") !== "true";
    b.setAttribute("aria-pressed", String(on));
    fn(on);
  });
}
toggleBtn("t-phase", on => { S.showPhase = on; draw(); });
toggleBtn("t-post",  on => { S.showPost  = on; draw(); });
toggleBtn("t-race",  on => { S.showRace  = on; draw(); });
toggleBtn("s-waist", on => { S.series.waist  = on; draw(); });
toggleBtn("s-weight",on => { S.series.weight = on; draw(); });
toggleBtn("s-vo2max",on => { S.series.vo2max = on; draw(); });
toggleBtn("s-index", on => { S.series.index  = on; draw(); });
toggleBtn("t-table", on => { document.getElementById("datatable").hidden = !on; });

/* ---------- tables & lists ---------- */
function buildTable() {
  document.getElementById("tbody").innerHTML = J.waist_in.map(q => {
    const we = J.weight_lb.find(z => z.d === q.d);
    let note = q.unverified ? "tape reading unverified" : "";
    if (!we) note = note ? note + "; no home-scale reading" : "no home-scale reading";
    return `<tr data-d="${q.d}"><td>${fmt(t(q.d))}</td><td>${q.v.toFixed(2)}</td>` +
           `<td>${we ? we.v.toFixed(1) : "—"}</td>` +
           `<td style="text-align:left;color:var(--text-faint);white-space:normal">${note || "—"}</td></tr>`;
  }).join("");
  document.getElementById("tbody").addEventListener("click", e => {
    const tr = e.target.closest("tr[data-d]");
    if (tr) select({ kind:"reading", d: tr.dataset.d, ts: t(tr.dataset.d) });
  });
}

function buildPhaseTable() {
  document.getElementById("phasebody").innerHTML = J.phases.map(p => {
    const nb = p.tier === "notebook";
    const evid = nb ? `${p.n} readings` : `${p.cov}%`;
    const thinEvid = nb ? p.n < 4 : p.cov < 40;
    return `<tr data-ph="${p.id}" style="cursor:pointer"${nb ? ' class="nb"' : ""}>` +
      `<td>${p.id} · ${p.name}${nb ? ' <span class="tierbadge">notebook</span>' : ""}</td>` +
      `<td>${fmt(t(p.from))} – ${fmt(t(p.to))}</td>` +
      `<td${p.rate ? "" : ' class="thin"'}>${p.rate || "no rate"}</td>` +
      `<td>${p.net}${p.waist ? ` <span style="color:var(--text-faint)">· ${p.waist}</span>` : ""}</td>` +
      `<td${thinEvid ? ' class="thin"' : ""}>${evid}</td></tr>`;
  }).join("");
  document.getElementById("phasebody").addEventListener("click", e => {
    const tr = e.target.closest("tr[data-ph]");
    if (!tr) return;
    const p = J.phases.find(z => z.id === tr.dataset.ph);
    setRange(t(p.from) - 20*DAY, t(p.to) + 20*DAY, null);
    select({ kind:"phase", p });
  });
}

/* Titles are ordinary links and navigate, because that is what a list of posts
   should do. Hovering a row previews it on the chart instead. */
function buildPostList() {
  document.getElementById("postlist").innerHTML = J.posts.map((po, i) => {
    const ph = phaseAt(t(po.d));
    const wa = po.pre ? null : nearestWithin(J.waist_in, t(po.d), 45);
    const state = po.pre ? "before the record began"
      : (wa ? "waist " + wa.v.toFixed(2) + " in" : "no reading nearby") + (ph ? " · Phase " + ph.id : "");
    return `<li data-i="${i}"><span class="date">${fmt(t(po.d))}</span>` +
           `<a class="ttl" href="${po.url}">${po.title}</a>` +
           `<span class="state">${state}</span></li>`;
  }).join("");

  document.querySelectorAll("#postlist li").forEach(li => {
    const po = J.posts[+li.dataset.i];
    li.addEventListener("pointerenter", e => {
      if (e.pointerType === "mouse") { S.sel = { kind:"post", po, ts: po.pre ? null : t(po.d) }; renderReadout(); draw(); syncLists(); }
    });
    li.addEventListener("click", e => {
      // let the title link navigate; a click anywhere else selects
      if (e.target.closest("a")) return;
      select({ kind:"post", po });
    });
  });
}

function syncLists() {
  const sel = S.sel;
  document.querySelectorAll("#postlist li").forEach(li =>
    li.classList.toggle("on", !!sel && sel.kind === "post" && J.posts[+li.dataset.i].d === sel.po.d));
  document.querySelectorAll("#tbody tr").forEach(tr =>
    tr.classList.toggle("on", !!sel && sel.kind === "reading" && tr.dataset.d === sel.d));
}

/* ---------- deep link: /journey#fat-nerd-revisited ---------- */
function fromHash() {
  const h = decodeURIComponent(location.hash.replace(/^#/, ""));
  if (!h) return;
  const po = J.posts.find(p => slug(p.title) === h);
  if (po) { select({ kind:"post", po }, { quiet:true }); return; }
  const ph = J.phases.find(p => slug(p.id + "-" + p.name) === h || p.id.toLowerCase() === h);
  if (ph) select({ kind:"phase", p: ph }, { quiet:true });
}
window.addEventListener("hashchange", fromHash);

buildTable();
buildPhaseTable();
buildPostList();
draw();
renderReadout();
fromHash();
